INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_68e1899c29197fbfc369','El Saleheya El Gadida University','جامعة الصالحية الجديدة','SGU','new-salhia-university','PRIVATE','Egypt','مصر','New Salhia','الصالحية الجديدة','El Saleheya El Gadida University is a private university established by Presidential Decree No. 656 of 2020 and accredited by the Ministry of Higher Education, located in New Salhia, Sharqia Governorate. It has faculties of dentistry, pharmacy (PharmD and Clinical PharmD), physical therapy, computers and information, and international management and economics (in Arabic or English). Fees for new students in 2026/2027 range from 30,000 to 125,000 EGP a year. Admission, registration and fee payment are done only on campus.','جامعة الصالحية الجديدة جامعة خاصة أُنشئت بالقرار الجمهوري رقم 656 لسنة 2020 ومعتمدة من وزارة التعليم العالي والبحث العلمي، ومقرها مدينة الصالحية الجديدة بمحافظة الشرقية. تضم كليات طب الأسنان، والصيدلة (فارم دي وفارم دي إكلينيكال)، والعلاج الطبيعي، والحاسبات والمعلومات، والإدارة والاقتصاد الدولي (بالعربية أو الإنجليزية). تتراوح مصروفات الطلاب المستجدين للعام 2026/2027 بين 30 و125 ألف جنيه سنويًا، وتتم إجراءات القبول والتسجيل وسداد المصروفات داخل مقر الجامعة فقط.','https://sgu.edu.eg','/img/universities/new-salhia-university/logo.png',NULL,2020,'Southern Zone, Block 8, New Salhia, Sharqia Governorate','المنطقة الجنوبية، بلوك 8، الصالحية الجديدة، محافظة الشرقية','01557750450','admin@sgu.edu.eg',30.616651,31.9393853,now(),now(),now());
