INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_8c61c4b156695591ee9e','New Egypt University','جامعة مصر الجديدة','NEU','new-egypt-university','PRIVATE','Egypt','مصر','6th of October City','مدينة 6 أكتوبر','New Egypt University is a private university in 6th of October City, established by presidential decree and taking its first students in 2026/2027. It has four faculties: pharmacy (PharmD and Clinical PharmD, 5 years), physical therapy (5 years), computers and artificial intelligence (4 years) and administrative sciences in Arabic or English (4 years). Listed 2026/2027 fees run from 62,630 to 146,730 EGP before discounts; the first intake gets a 25% discount, plus 5% for early payment.','جامعة مصر الجديدة جامعة خاصة بمدينة السادس من أكتوبر، أُنشئت بقرار جمهوري وتستقبل أول دفعة في العام الدراسي 2026/2027. تضم أربع كليات: الصيدلة (فارم دي وفارم دي إكلينيكال، 5 سنوات)، والعلاج الطبيعي (5 سنوات)، والحاسبات والذكاء الاصطناعي (4 سنوات)، والعلوم الإدارية بالعربية أو الإنجليزية (4 سنوات). تتراوح مصروفات العام 2026/2027 بين 62,630 و146,730 جنيهًا قبل الخصم، مع خصم 25% للدفعة الأولى و5% إضافية للسداد المبكر.','https://neu.edu.eg','/img/universities/new-egypt-university/logo.png','/img/universities/new-egypt-university/cover.jpg',NULL,'Fourth Industrial Zone, 6th of October City, Giza','المنطقة الرابعة الصناعية، مدينة السادس من أكتوبر، الجيزة',NULL,'info@neu.edu.eg',29.94,30.890611,now(),now(),now());
