INSERT INTO "University" ("id","name","nameAr","acronym","slug","type","country","countryAr","city","cityAr","description","descriptionAr","websiteUrl","logoUrl","coverImageUrl","establishedYear","addressLine","addressLineAr","phone","email","latitude","longitude","publishedAt","createdAt","updatedAt") VALUES ('univ_9a335cf7a54a38ae53a7','Egyptian University in Alamein','الجامعة المصرية بالعلمين','EUA','egyptian-university-in-alamein','PRIVATE','Egypt','مصر','New Alamein','العلمين الجديدة','The Egyptian University in Alamein is a private university created by a 2022 presidential decree, with its campus in Tal El Eisa, New Alamein City, Matrouh. Its faculties are engineering, computers and artificial intelligence, medicine, dentistry, physical therapy, and management and political science, and it develops programs with Brunel University London for dual degrees. The Faculty of Computers and AI is among the first to open, with teaching starting in 2026/2027. Fees have not been published yet.','الجامعة المصرية بالعلمين جامعة خاصة أُنشئت بقرار جمهوري عام 2022، ويقع حرمها في منطقة تل العيس بمدينة العلمين الجديدة بمحافظة مطروح. تضم كليات الهندسة، والحاسبات والذكاء الاصطناعي، والطب، وطب الأسنان، والعلاج الطبيعي، والإدارة والعلوم السياسية، وتطور برامجها بالتعاون مع جامعة برونيل لندن لمنح درجات مزدوجة. كلية الحاسبات والذكاء الاصطناعي من أوائل الكليات التي تبدأ الدراسة بها في العام الجامعي 2026/2027. لم تُعلن المصروفات بعد.','https://eua.edu.eg','/img/universities/egyptian-university-in-alamein/logo.webp','/img/universities/egyptian-university-in-alamein/cover.jpg',2022,'Tal El Eisa, New Alamein City, Matrouh Governorate','منطقة تل العيس، مدينة العلمين الجديدة، محافظة مطروح',NULL,'info@eua.edu.eg',30.9278875,28.7901719,now(),now(),now());
